{
  "name": "@reticlehq/web-extension",
  "version": "0.1.0",
  "private": true,
  "description": "Hands a tab of a real browser to Reticle, so an agent can read and act on the page.",
  "type": "module",
  "license": "Apache-2.0",
  "scripts": {
    "install-host": "node install.mjs",
    "test:handoff": "node test/handoff.mjs"
  },
  "dependencies": {
    "@reticlehq/browser": "^3.10.10"
  }
}

// Gets the Reticle extension ready for a browser, on macOS:
//
//   node install.mjs --browser dia        (or chrome, or chromium)
//   node install.mjs --dir <NativeMessagingHosts folder> [--port 4400] [--reader <reticle-inject.js>]
//
// It copies the reader of `@reticlehq/browser` into the extension folder, and writes the manifest
// that lets the browser start the native host. Then load the extension folder once in each browser
// profile: open the extensions page, turn on developer mode, and choose "Load unpacked".
import { createHash } from 'node:crypto';
import { chmodSync, copyFileSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { DEFAULT_PORT, HOST_NAME } from './host/constants.mjs';

const here = fileURLToPath(new URL('.', import.meta.url));
const support = join(homedir(), 'Library', 'Application Support');
/** Where the host runs from: a folder that every browser may read. */
const HOST_HOME = join(support, 'Reticle', 'web-extension');
const CHROME_HOSTS = join(support, 'Google', 'Chrome', 'NativeMessagingHosts');
/** Where each browser looks for a native host. Dia looks in Chrome's folder, not in its own. */
const HOSTS_OF = {
  dia: CHROME_HOSTS,
  chrome: CHROME_HOSTS,
  chromium: join(support, 'Chromium', 'NativeMessagingHosts'),
};

const arg = (name) => {
  const at = process.argv.indexOf(`--${name}`);
  return at > 0 ? process.argv[at + 1] : undefined;
};

/** The ID a Chromium browser gives the extension: from the public key in its manifest. */
export function extensionId(key) {
  const hash = createHash('sha256').update(Buffer.from(key, 'base64')).digest('hex').slice(0, 32);
  return [...hash].map((digit) => String.fromCharCode(97 + parseInt(digit, 16))).join('');
}

/** The reader of `@reticlehq/browser`: the one installed here, or the file `--reader` names. */
function readerPath(given) {
  return given ?? createRequire(import.meta.url).resolve('@reticlehq/browser/inject');
}

export function install({ browser, dir = HOSTS_OF[browser ?? ''], port = DEFAULT_PORT, reader }) {
  if (dir === undefined) {
    throw new Error('Give a browser (dia, chrome or chromium) or the NativeMessagingHosts folder.');
  }
  copyFileSync(readerPath(reader), join(here, 'extension', 'reticle-inject.js'));
  // The host is copied out of this folder. macOS counts a host as the browser that starts it, and
  // a browser with no right to ~/Documents cannot read a host that is there: Dia started it, and it
  // ended before its first line.
  mkdirSync(HOST_HOME, { recursive: true });
  for (const file of ['host.mjs', 'constants.mjs']) {
    copyFileSync(join(here, 'host', file), join(HOST_HOME, file));
  }
  // A browser starts the host with a short PATH, so the host is started through the full path of
  // this Node.
  const start = join(HOST_HOME, 'host.sh');
  writeFileSync(
    start,
    `#!/bin/sh\nexec "${process.execPath}" "${join(HOST_HOME, 'host.mjs')}" --port ${String(port)} "$@"\n`,
  );
  chmodSync(start, 0o755);
  const { key } = JSON.parse(readFileSync(join(here, 'extension', 'manifest.json'), 'utf8'));
  mkdirSync(dir, { recursive: true });
  const manifest = join(dir, `${HOST_NAME}.json`);
  writeFileSync(
    manifest,
    `${JSON.stringify(
      {
        name: HOST_NAME,
        description: 'Carries the pages handed to Reticle to the Reticle bridge.',
        path: start,
        type: 'stdio',
        allowed_origins: [`chrome-extension://${extensionId(key)}/`],
      },
      null,
      2,
    )}\n`,
  );
  return { manifest, extension: join(here, 'extension') };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const browser = arg('browser');
  const dir = arg('dir') ?? HOSTS_OF[browser ?? ''];
  if (dir === undefined) {
    process.stderr.write('Give --browser dia, chrome or chromium, or --dir <NativeMessagingHosts folder>.\n');
    process.exit(2);
  }
  const port = arg('port') === undefined ? DEFAULT_PORT : Number(arg('port'));
  const done = install({ browser, dir, port, reader: arg('reader') });
  process.stdout.write(
    `Wrote ${done.manifest}.\nNow load ${done.extension} once in each profile: the extensions page, developer mode, "Load unpacked".\n`,
  );
}

// Reticle's desktop realm hands a tab of the real Dia to browser-level Reticle, through this
// extension, and a fill and a press are proved on the page with the tools an agent has.
//
// The page forbids every connection of its own (`connect-src 'none'`), and the reader still
// connects: it goes through the extension and its native host, not through the page.
//
//   RETICLE_REPO=../reticle node test/handoff.mjs
//
// macOS, Dia with this extension loaded, the Accessibility permission, and a built Reticle
// checkout with the desktop realm. Not a gate: it takes the screen for a few seconds. It opens a
// tab of its own and closes it at the end. It uses a bridge of its own on port 14459, and puts the
// native host back on the usual port at the end.
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { createServer } from 'node:http';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { setTimeout as sleep } from 'node:timers/promises';
import { fileURLToPath } from 'node:url';

import { install } from '../install.mjs';
import { DEFAULT_PORT, TOKEN_DIR, TOKEN_FILE } from '../host/constants.mjs';

// A built checkout of Reticle: its bridge, and its desktop realm.
const reticle = new URL(`${process.env.RETICLE_REPO ?? '../../reticle'}/`, import.meta.url);
const at = (path) => new URL(path, reticle).href;
const { ActionType, ReticleCommand } = await import(at('core/dist/index.js'));
const { MacDriver, PeerCommands } = await import(at('adapters/realm/computer-use/dist/index.js'));
const { Bridge } = await import(at('server/dist/portal/bridge/bridge.js'));
const { callTool, makeDeps, waitUntil } = await import(
  at('server/dist/portal/bridge/bridge.test-harness.js')
);
const native = fileURLToPath(new URL('adapters/realm/computer-use/native/mac/', reticle));
const reader = fileURLToPath(new URL('adapters/realm/browser/dist/reticle-inject.js', reticle));

const osa = (script) => execFileSync('osascript', ['-e', script], { encoding: 'utf8' }).trim();
const PORT = 14459;
const NOTE = 'Handed over in Dia';

// The host reads the person's pairing token (`~/.reticle/pairing-token`): a browser passes it no
// other folder. The daemon writes that file on its first start.
let token;
try {
  token = [REDACTED], TOKEN_DIR, TOKEN_FILE), 'utf8').trim();
} catch {
  console.error('handoff: no ~/.reticle/pairing-token. Start the Reticle daemon once. Nothing was run.');
  process.exit(0);
}
const bridge = new Bridge({ port: PORT, token });
await bridge.ready;
const deps = makeDeps(bridge);
install({ browser: 'dia', port: PORT, reader });

const page = readFileSync(`${native}form.html`, 'utf8');
const server = createServer((_request, response) => {
  response.writeHead(200, {
    'content-type': 'text/html; charset=utf-8',
    'content-security-policy': "connect-src 'none'; script-src 'self' 'unsafe-inline'",
  });
  response.end(page);
});
await new Promise((done) => server.listen(0, '127.0.0.1', done));
const url = `http://127.0.0.1:${String(server.address().port)}/`;

osa(`tell application "Dia" to tell front window to make new tab with properties {URL:"${url}"}`);
try {
  osa('tell application "Dia" to activate');
  await sleep(2000);
  assert.equal(osa('tell application "Dia" to get URL of active tab of front window'), url);
  const pid = Number(execFileSync('pgrep', ['-x', 'Dia'], { encoding: 'utf8' }).split('\n')[0]);
  const desktop = new PeerCommands({
    driver: new MacDriver({ helper: `${native}build/reticle-ax`, app: 'Dia', pid }),
    emit: () => undefined,
    foreground: true,
  });
  // With Stage Manager on, Dia has no window to read until it is in front.
  let window;
  for (let tries = 0; tries < 10 && window === undefined; tries += 1) {
    osa('tell application "Dia" to activate');
    await sleep(500);
    window = (await desktop.answer(ReticleCommand.QUERY, { role: 'window' })).elements[0];
  }
  assert.ok(window, 'Dia has no window to read');
  assert.equal(bridge.sessions.list().length, 0, 'a page joined before it was handed over');

  // The baton: the key of the extension, pressed in Dia as a person presses it.
  await desktop.answer(ReticleCommand.ACT, {
    ref: window.ref,
    action: ActionType.PRESS,
    args: { text: 'r', modifiers: ['Alt', 'Shift'], foreground: true, settleMs: 600 },
  });
  await waitUntil(() => bridge.sessions.list().length > 0, 8000);

  const tree = (await callTool(deps, 'reticle_snapshot', {})).tree;
  const refOf = (element) =>
    /ref=(e\d+)/.exec(tree.split('\n').find((line) => line.includes(`- ${element}`)) ?? '')?.[1];
  await callTool(deps, 'reticle_act', {
    ref: refOf('textbox "New note"'),
    action: 'fill',
    args: { value: NOTE },
  });
  const proved = await callTool(deps, 'reticle_act_and_wait', {
    ref: refOf('button "Add"'),
    action: 'click',
    timeout_ms: 3000,
    until: { kind: 'element', query: { role: 'listitem', name: NOTE }, state: 'visible' },
  });
  assert.equal(proved.verified, 'yes', `the press was not proved: ${String(proved.because)}`);
  console.error('handoff: the desktop realm handed a Dia tab over, and a press was proved on it');
} finally {
  if (osa('tell application "Dia" to get URL of active tab of front window') === url) {
    osa('tell application "Dia" to close active tab of front window');
  }
  install({ browser: 'dia', port: DEFAULT_PORT, reader });
  server.close();
  await bridge.close();
  setTimeout(() => process.exit(process.exitCode ?? 0), 300);
}

// In the main world of the page, after the reader: connect it. The URL has the bridge's path, so
// the tunnel takes it. The native host knows the real port, and puts the real pairing token in the
// HELLO in place of this placeholder.
//
// The placeholder is there because the reader refuses a page that is not on localhost when it has
// no token: discord.com and example.com joined nothing. It opens nothing by itself, because only
// the host's token is checked by the bridge.
globalThis.__reticleInstance?.connect({
  url: 'ws://127.0.0.1:4400/reticle',
  allowNonLocalhost: true,
  lease: true,
  token: '[REDACTED]',
  // No HUD in the page: the desktop realm's HUD shows the work of the whole computer, the page's
  // actions with it. Two HUDs for one task was one too many.
  present: false,
});

// In the isolated world of the page: carries the frames of the reader's tunnel between the page and
// the extension. Runs once for each document.
(() => {
  if (globalThis.__reticleRelay === true) {
    return;
  }
  globalThis.__reticleRelay = true;
  const TO_RELAY = '__reticleTunnel';
  const TO_PAGE = '__reticleTunnelBack';
  let port;
  window.addEventListener('message', (event) => {
    if (event.source !== window || event.data?.[TO_RELAY] !== true) {
      return;
    }
    const { type, data } = event.data;
    if (type === 'open') {
      port?.disconnect();
      port = chrome.runtime.connect({ name: 'reticle-tunnel' });
      port.onMessage.addListener((frame) => {
        window.postMessage({ ...frame, [TO_PAGE]: true }, location.origin);
      });
      port.onDisconnect.addListener(() => {
        window.postMessage({ type: 'close', code: 1006, reason: 'relay gone', [TO_PAGE]: true }, location.origin);
        port = undefined;
      });
    }
    port?.postMessage({ type, data });
    if (type === 'close') {
      port?.disconnect();
      port = undefined;
    }
  });
})();

// In the main world of the page, before the reader: a socket to the bridge that goes through the
// extension. The reader opens `new WebSocket(url)` with the bridge's path; that one socket is a
// tunnel, and every other socket of the page is the real one. A ws:// socket from an https page is
// refused by the browser, and a page's connect-src rule can refuse it too: the tunnel has neither.
//
// ponytail: the page can read and post the same window messages. It can only speak as its own
// session, and the pairing token is added by the native host, outside the page.
(() => {
  if (globalThis.__reticleTunnel === true) {
    return;
  }
  globalThis.__reticleTunnel = true;
  // The reader's schemas make no `new Function` (a page's CSP can refuse it), as for the lease reader.
  (globalThis.__zod_globalConfig ??= {}).jitless ??= true;
  const TO_RELAY = '__reticleTunnel';
  const TO_PAGE = '__reticleTunnelBack';
  const BRIDGE_PATH = '/reticle';
  const Native = globalThis.WebSocket;

  class TunnelSocket {
    constructor(url) {
      this.url = url;
      this.readyState = Native.CONNECTING;
      this.onopen = null;
      this.onmessage = null;
      this.onclose = null;
      this.onerror = null;
      this.listen = (event) => {
        if (event.source !== window || event.data?.[TO_PAGE] !== true) {
          return;
        }
        const { type, data, code, reason } = event.data;
        if (type === 'open') {
          this.readyState = Native.OPEN;
          this.onopen?.(new Event('open'));
        } else if (type === 'message') {
          this.onmessage?.(new MessageEvent('message', { data }));
        } else if (type === 'close') {
          this.#closed(code ?? 1000, reason ?? '');
        }
      };
      window.addEventListener('message', this.listen);
      window.postMessage({ [TO_RELAY]: true, type: 'open' }, location.origin);
    }

    send(text) {
      if (this.readyState === Native.OPEN) {
        window.postMessage({ [TO_RELAY]: true, type: 'send', data: String(text) }, location.origin);
      }
    }

    close() {
      if (this.readyState !== Native.CLOSED) {
        window.postMessage({ [TO_RELAY]: true, type: 'close' }, location.origin);
        this.#closed(1000, '');
      }
    }

    #closed(code, reason) {
      if (this.readyState === Native.CLOSED) {
        return;
      }
      this.readyState = Native.CLOSED;
      window.removeEventListener('message', this.listen);
      this.onclose?.(new CloseEvent('close', { code, reason }));
    }
  }

  const isBridge = (url) => {
    try {
      return new URL(String(url), location.href).pathname === BRIDGE_PATH;
    } catch {
      return false;
    }
  };
  class Socket extends Native {
    constructor(url, protocols) {
      if (isBridge(url)) {
        return new TunnelSocket(url);
      }
      super(url, protocols);
    }
  }
  globalThis.WebSocket = Socket;
})();

// Hands a tab to Reticle. A press on the toolbar button of the extension (a person, or the desktop
// realm through the Extensions menu) puts Reticle's reader into the page of that tab. The reader
// talks to the bridge through this extension and its native host, so the page's own rules for
// connections do not apply, and the pairing token never goes into the page.
//
// A tab that was handed over gets the reader again after each load, until the tab closes or a
// second press hands it back.

const HOST = 'sh.reticle.relay';
const HANDED = 'handed';
const TUNNEL = 'reticle-tunnel';

async function handedTabs() {
  const kept = await chrome.storage.session.get(HANDED);
  return new Set(kept[HANDED] ?? []);
}

async function keep(tabs) {
  await chrome.storage.session.set({ [HANDED]: [...tabs] });
}

async function giveReader(tabId) {
  await chrome.scripting.executeScript({ target: { tabId }, files: ['relay.js'], world: 'ISOLATED' });
  // One reader for each page. A second copy of the reader made a second HUD and a second set of
  // styles: a press on a tab that had one already put the HUD in the wrong place.
  const [has] = await chrome.scripting.executeScript({
    target: { tabId },
    world: 'MAIN',
    func: () => undefined !== globalThis.__reticleInstance,
  });
  await chrome.scripting.executeScript({
    target: { tabId },
    files: true === has?.result ? ['connect.js'] : ['tunnel.js', 'reticle-inject.js', 'connect.js'],
    world: 'MAIN',
  });
}

chrome.action.onClicked.addListener(async (tab) => {
  if (tab.id === undefined) {
    return;
  }
  const tabs = await handedTabs();
  // A second press hands the tab back: the reader stops, and a reload gives it no reader again.
  // A press on the wrong tab must be undone by the same key that made it.
  if (tabs.has(tab.id)) {
    tabs.delete(tab.id);
    await keep(tabs);
    await chrome.scripting
      .executeScript({
        target: { tabId: tab.id },
        world: 'MAIN',
        func: () => globalThis.__reticleInstance?.disconnect(),
      })
      .catch(() => undefined);
    await chrome.action.setBadgeText({ tabId: tab.id, text: '' });
    return;
  }
  tabs.add(tab.id);
  await keep(tabs);
  await giveReader(tab.id);
  await chrome.action.setBadgeText({ tabId: tab.id, text: 'on' });
});

chrome.tabs.onUpdated.addListener(async (tabId, change) => {
  if (change.status !== 'complete' || !(await handedTabs()).has(tabId)) {
    return;
  }
  await giveReader(tabId).catch(() => undefined);
  await chrome.action.setBadgeText({ tabId, text: 'on' });
});

chrome.tabs.onRemoved.addListener(async (tabId) => {
  const tabs = await handedTabs();
  if (tabs.delete(tabId)) {
    await keep(tabs);
  }
});

// One connection to the bridge for each page: the relay script of the page opens a port, and the
// port gets a native host of its own. What one side says, the other side gets.
chrome.runtime.onConnect.addListener((port) => {
  if (port.name !== TUNNEL || port.sender?.tab?.id === undefined) {
    port.disconnect();
    return;
  }
  const host = chrome.runtime.connectNative(HOST);
  port.onMessage.addListener((message) => host.postMessage(message));
  host.onMessage.addListener((message) => port.postMessage(message));
  port.onDisconnect.addListener(() => host.disconnect());
  host.onDisconnect.addListener(() => {
    const why = chrome.runtime.lastError?.message ?? 'the native host stopped';
    port.postMessage({ type: 'close', code: 1011, reason: why });
    port.disconnect();
  });
});

{
  "manifest_version": 3,
  "name": "Reticle",
  "version": "0.1.0",
  "description": "Hands the tab you are on to Reticle, so an agent can read and act on the page.",
  "key": "",
  "minimum_chrome_version": "111",
  "permissions": [
    "activeTab",
    "scripting",
    "nativeMessaging",
    "storage",
    "tabs"
  ],
  "host_permissions": [
    "<all_urls>"
  ],
  "background": {
    "service_worker": "background.js"
  },
  "action": {
    "default_title": "Hand this tab to Reticle"
  },
  "commands": {
    "_execute_action": {
      "suggested_key": {
        "default": "Alt+Shift+R"
      },
      "description": "Hand this tab to Reticle"
    }
  }
}
